183	static int sifli_setup(uart_dev_t *serial)
184	{
185	    struct sifli_uart *uart;
186	    uart = (struct sifli_uart *)serial->priv;
187	    struct serial_configure *cfg=&uart->ser_cfg;
188	
189	    uart->handle.Instance          = uart->config->Instance;
190	    uart->handle.Init.BaudRate     = cfg->baud_rate;
191	    uart->handle.Init.HwFlowCtl    = cfg->hwfc;
192	    uart->handle.Init.HwFlowCtl    <<= USART_CR3_RTSE_Pos;
193	    uart->handle.Init.Mode         = UART_MODE_TX_RX;
194	    uart->handle.Init.OverSampling = UART_OVERSAMPLING_16;
195	
196	    if (cfg->parity && cfg->data_bits < DATA_BITS_9)
197	        cfg->data_bits++;                           // parity is part of data
198	
199	    switch (cfg->data_bits)
200	    {
201	    case DATA_BITS_6:
202	        uart->handle.Init.WordLength = UART_WORDLENGTH_6B;
203	        break;
204	    case DATA_BITS_7:
205	        uart->handle.Init.WordLength = UART_WORDLENGTH_7B;
206	        break;
207	    case DATA_BITS_8:
208	        uart->handle.Init.WordLength = UART_WORDLENGTH_8B;
209	        break;
210	    case DATA_BITS_9:
211	        uart->handle.Init.WordLength = UART_WORDLENGTH_9B;
212	        break;
213	    default:
214	        uart->handle.Init.WordLength = UART_WORDLENGTH_8B;
215	        break;
216	    }
217	    switch (cfg->stop_bits)
218	    {
219	    case STOP_BITS_1:
220	        uart->handle.Init.StopBits   = UART_STOPBITS_1;
221	        break;
222	    case STOP_BITS_2:
223	        uart->handle.Init.StopBits   = UART_STOPBITS_2;
224	        break;
225	    case STOP_BITS_3:
226	        uart->handle.Init.StopBits   = UART_STOPBITS_0_5;
227	        break;
228	    case STOP_BITS_4:
229	        uart->handle.Init.StopBits   = UART_STOPBITS_1_5;
230	        break;
231	    default:
232	        uart->handle.Init.StopBits   = UART_STOPBITS_1;
233	        break;
234	    }
235	    switch (cfg->parity)
236	    {
237	    case PARITY_NONE:
238	        uart->handle.Init.Parity     = UART_PARITY_NONE;
239	        break;
240	    case PARITY_ODD:
241	        uart->handle.Init.Parity     = UART_PARITY_ODD;
242	        break;
243	    case PARITY_EVEN:
244	        uart->handle.Init.Parity     = UART_PARITY_EVEN;
245	        break;
246	    default:
247	        uart->handle.Init.Parity     = UART_PARITY_NONE;
248	        break;
249	    }
250	
251	    if (HAL_UART_Init(&uart->handle) != HAL_OK)
252	    {
253	        return -EINVAL;
254	    }
255	
256	    return OK;
257	}
