399	static int sifli_receive(struct uart_dev_s *dev, unsigned int *status)
400	{
401	    int ch;
402	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
403	
404	    ch = -1;
405	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_RXNE) != RESET)
406	        ch = __HAL_UART_GETC(&uart->handle);
407	    if (status)
408	      *status = 0x00;
409	    return ch;
410	}
