412	static void sifli_rxint(struct uart_dev_s *dev, bool enable)
413	{
414	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
415	
416	    /* DMA RX: IDLE + EIE must stay enabled. NuttX briefly calls rxint(false)
417	     * while waiting; masking them leaves circular DMA running with no kick,
418	     * so GNSS looks dead until the bounce wraps.
419	     *
420	     * uart_read() / poll waiters never call rxavailable(), so harvest here
421	     * when RX is (re)enabled: bounce bytes become visible in the SW ring.
422	     */
423	    if (uart->uart_rx_dma_flag)
424	    {
425	        if (enable)
426	        {
427	            __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_IDLE);
428	            if (uart->handle.Instance != NULL)
429	            {
430	                SET_BIT(uart->handle.Instance->CR3, USART_CR3_EIE);
431	            }
432	
433	            up_enable_irq(uart->config->irq_type+16);
434	            sifli_uart_dma_poll(uart);
435	        }
436	    }
437	    else
438	    {
439	        if (enable)
440	        {
441	            /* Enable UART RXNE interrupt */
442	            __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_RXNE);
443	            up_enable_irq(uart->config->irq_type+16);
444	        }
445	        else
446	        {
447	            /* Disable UART RXNE interrupt */
448	            __HAL_UART_DISABLE_IT(&(uart->handle), UART_IT_RXNE);
449	            up_disable_irq(uart->config->irq_type+16);
450	        }
451	    }
452	}
