454	/* Circular DMA + IDLE/HT/TC harvest.
455	 * 1 Mbps USB-UART (CH340) inserts gaps >> 1 character time, so Normal DMA
456	 * that stops on IDLE then rearms drops the next packet in the FIFO.
457	 * Keep DMAR running; copy bounce[pos .. NDTR) into the NuttX RX ring.
458	 *
459	 * DMA1 channels are pinned at serialinit (KeepAlloc, same as NSH console).
460	 * Close only stops the engine; the pool slot and NVIC hook stay for life.
461	 * GNSS USART2 RX stays on CH4.
462	 */
463	
464	static IRQn_Type sifli_uart_dma_irqn(DMA_HandleTypeDef *hdma)
465	{
466	    IRQn_Type base;
467	
468	    if (hdma == NULL || hdma->DmaBaseAddress == NULL)
469	    {
470	        return (IRQn_Type)0;
471	    }
472	
473	    if (hdma->DmaBaseAddress == DMA1)
474	    {
475	        base = DMAC1_CH1_IRQn;
476	    }
477	#ifdef DMA2
478	    else if (hdma->DmaBaseAddress == DMA2)
479	    {
480	        base = DMAC2_CH1_IRQn;
481	    }
482	#endif
483	    else
484	    {
485	        return (IRQn_Type)0;
486	    }
487	
488	    return (IRQn_Type)(base + (int)(hdma->ChannelIndex >> 2));
489	}
490	
491	static void sifli_uart_dma_irq_sync(struct sifli_uart *uart)
492	{
493	    IRQn_Type irq;
494	
495	    if (!uart->uart_rx_dma_flag || uart->handle.hdmarx == NULL)
496	    {
497	        return;
498	    }
499	
500	    irq = sifli_uart_dma_irqn(uart->handle.hdmarx);
501	    if (irq <= 0)
502	    {
503	        return;
504	    }
505	
506	    if (uart->dma_nvic_irq == (int16_t)irq)
507	    {
508	        up_enable_irq((int)irq + 16);
509	        return;
510	    }
511	
512	    if (uart->dma_nvic_irq >= 0)
513	    {
514	        up_disable_irq((int)uart->dma_nvic_irq + 16);
515	        irq_detach((int)uart->dma_nvic_irq + 16);
516	        uart->dma_nvic_irq = -1;
517	    }
518	
519	    if (irq_attach((int)irq + 16, uart_dma_isr, uart) == OK)
520	    {
521	        up_enable_irq((int)irq + 16);
522	        uart->dma_nvic_irq = (int16_t)irq;
523	    }
524	}
