819	static void sifli_uart_dma_bind(struct sifli_uart *uart)
820	{
821	    HAL_RCC_EnableModule(RCC_MOD_DMAC1);
822	    __HAL_LINKDMA(&(uart->handle), hdmarx, uart->dma_rx.handle);
823	    uart->handle.hdmarx->Instance = uart->config->dma_rx->Instance;
824	    uart->handle.hdmarx->Init.Request = uart->config->dma_rx->request;
825	    uart->handle.hdmarx->Init.Direction = DMA_PERIPH_TO_MEMORY;
826	    uart->handle.hdmarx->Init.PeriphInc = DMA_PINC_DISABLE;
827	    uart->handle.hdmarx->Init.MemInc = DMA_MINC_ENABLE;
828	    uart->handle.hdmarx->Init.PeriphDataAlignment = DMA_PDATAALIGN_BYTE;
829	    uart->handle.hdmarx->Init.MemDataAlignment = DMA_MDATAALIGN_BYTE;
830	    uart->handle.hdmarx->Init.Mode = DMA_CIRCULAR;
831	    uart->handle.hdmarx->Init.Priority = DMA_PRIORITY_HIGH;
832	    uart->handle.hdmarx->Init.BurstSize = 1;
833	#ifdef DMA_SUPPORT_DYN_CHANNEL_ALLOC
834	    uart->handle.hdmarx->Init.IrqPrio = uart->config->dma_rx->dma_irq_prio;
835	    uart->handle.hdmarx->KeepAlloc = 1;
836	#endif
837	}
