1087	/****************************************************************************
1088	 * Name: nrf53_attach
1089	 *
1090	 * Description:
1091	 *   Configure the UART to operation in interrupt driven mode.  This method
1092	 *   is called when the serial port is opened.  Normally, this is just after
1093	 *   the the setup() method is called, however, the serial console may
1094	 *   operate in a non-interrupt driven mode during the boot phase.
1095	 *
1096	 *   RX and TX interrupts are not enabled when by the attach method (unless
1097	 *   the hardware supports multiple levels of interrupt enabling).
1098	 *   The RX and TX interrupts are not enabled until the txint() and rxint()
1099	 *   methods are called.
1100	 *
1101	 ****************************************************************************/
1102	
1103	static int sifli_attach(struct uart_dev_s *dev)
1104	{
1105	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
1106	    int ret;
1107	
1108	    /* sifli_attach called */
1109	    
1110	    //_info("recv %p\n", &(dev->recv));
1111	    // Start to receive data.
1112	    sifli_dma_receive(dev);
1113	
1114	    /* Attach and enable the IRQ(s).  The interrupts are (probably) still
1115	    * disabled in the C2 register.
1116	    */
1117	    ret = irq_attach(uart->config->irq_type+16, uart_isr, uart);
1118	    if (ret == OK) {
1119	        up_enable_irq(uart->config->irq_type+16);
1120	    }
1121	
1122	    sifli_uart_dma_irq_sync(uart);
1123	    return ret;
1124	}
1125	
1126	/****************************************************************************
1127	 * Name: nrf53_detach
1128	 *
1129	 * Description:
1130	 *   Detach UART interrupts.  This method is called when the serial port is
1131	 *   closed normally just before the shutdown method is called.
1132	 *   The exception is the serial console which is never shutdown.
1133	 *
1134	 ****************************************************************************/
1135	
1136	static void sifli_detach(struct uart_dev_s *dev)
1137	{
1138	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
1139	
1140	    /* UART IRQ only. DMA channel + NVIC stay pinned from serialinit. */
1141	    up_disable_irq(uart->config->irq_type+16);
1142	    irq_detach(uart->config->irq_type+16);
1143	}
1144	
1145	
1146	/****************************************************************************
1147	 * Name: sifli_shutdown
1148	 *
1149	 * Description:
1150	 *   Disable the UART.  This method is called when the serial
1151	 *   port is closed
1152	 *
1153	 ****************************************************************************/
1154	
1155	static void sifli_shutdown(struct uart_dev_s *dev)
1156	{
1157	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
1158	
1159	    /* Stop the engine; KeepAlloc slot and DMA IRQ stay for the next open. */
1160	    if (uart->uart_rx_dma_flag)
1161	    {
1162	        sifli_uart_dma_stop(uart);
1163	    }
1164	
1165	    HAL_UART_DeInit(&uart->handle);
1166	}
