281	/** @brief 应用 ST7789 背光 PWM 占空比；0 关断。 */
282	static int lcd_bl_pwm_apply(uint8_t brightness_pct)
283	{
284	    GPT_OC_InitTypeDef oc_cfg;
285	    uint32_t timclk;
286	    uint64_t ticks;
287	    uint32_t prescaler;
288	    uint32_t period;
289	    uint32_t pulse;
290	
291	    if (brightness_pct == 0)
292	    {
293	        if (s_lcd_bl_pwm_running)
294	        {
295	            HAL_GPT_PWM_Stop(&s_lcd_bl_pwm, LCD_BL_PWM_TIM_CHANNEL);
296	            s_lcd_bl_pwm_running = false;
297	        }
298	
299	        s_bl_applied = 0;
300	        return 0;
301	    }
302	
303	    if (brightness_pct > LCD_BL_MAX_BRIGHTNESS_PCT)
304	    {
305	        brightness_pct = LCD_BL_MAX_BRIGHTNESS_PCT;
306	    }
307	
308	    if (s_lcd_bl_pwm.Instance == NULL)
309	    {
310	        memset(&s_lcd_bl_pwm, 0, sizeof(s_lcd_bl_pwm));
311	        s_lcd_bl_pwm.Instance = GPTIM2;
312	        s_lcd_bl_pwm.core     = GPTIM2_CORE;
313	    }
314	
315	    timclk = lcd_bl_pwm_timclk();
316	    if (timclk == 0)
317	    {
318	        return -1;
319	    }
320	
321	    ticks = (uint64_t)timclk / (uint64_t)LCD_BL_PWM_FREQ_HZ;
322	    if (ticks == 0)
323	    {
324	        ticks = 1;
325	    }
326	
327	    prescaler = (uint32_t)((ticks + 65535ULL - 1ULL) / 65535ULL);
328	    if (prescaler == 0)
329	    {
330	        prescaler = 1;
331	    }
332	
333	    period = (uint32_t)(ticks / prescaler);
334	    if (period == 0)
335	    {
336	        period = 1;
337	    }
338	    else if (period > 65535)
339	    {
340	        period = 65535;
341	    }
342	
343	    pulse = (uint32_t)(((uint64_t)brightness_pct * (uint64_t)period) / 100ULL);
344	    if (pulse > period)
345	    {
346	        pulse = period;
347	    }
348	
349	    if (s_lcd_bl_pwm_running && s_lcd_bl_pwm.Instance != NULL)
350	    {
351	        uint32_t per = s_lcd_bl_pwm.Init.Period + 1u;
352	
353	        if (per == 0u)
354	        {
355	            per = 1u;
356	        }
357	
358	        pulse = (uint32_t)(((uint64_t)brightness_pct * (uint64_t)per) / 100ULL);
359	        if (pulse > per)
360	        {
361	            pulse = per;
362	        }
363	
364	        s_lcd_bl_pwm.Instance->CCR1 = pulse;
365	        s_bl_applied = brightness_pct;
366	        return 0;
367	    }
368	
369	    if (s_lcd_bl_pwm_running)
370	    {
371	        HAL_GPT_PWM_Stop(&s_lcd_bl_pwm, LCD_BL_PWM_TIM_CHANNEL);
372	        s_lcd_bl_pwm_running = false;
373	    }
374	
375	    s_lcd_bl_pwm.Init.Prescaler         = prescaler - 1;
376	    s_lcd_bl_pwm.Init.CounterMode       = GPT_COUNTERMODE_UP;
377	    s_lcd_bl_pwm.Init.Period            = period - 1;
378	    s_lcd_bl_pwm.Init.RepetitionCounter = 0;
379	
380	    if (HAL_GPT_PWM_Init(&s_lcd_bl_pwm) != HAL_OK)
381	    {
382	        return -1;
383	    }
384	
385	    oc_cfg.OCMode       = GPT_OCMODE_PWM1;
386	    oc_cfg.Pulse        = pulse;
387	    oc_cfg.OCPolarity   = GPT_OCPOLARITY_HIGH;
388	    oc_cfg.OCNPolarity  = GPT_OCNPOLARITY_LOW;
389	    oc_cfg.OCFastMode   = GPT_OCFAST_DISABLE;
390	    oc_cfg.OCIdleState  = GPT_OCIDLESTATE_RESET;
391	    oc_cfg.OCNIdleState = GPT_OCNIDLESTATE_RESET;
392	
393	    if (HAL_GPT_PWM_ConfigChannel(&s_lcd_bl_pwm, &oc_cfg,
394	                                  LCD_BL_PWM_TIM_CHANNEL) != HAL_OK)
395	    {
396	        return -1;
397	    }
398	
399	    if (HAL_GPT_PWM_Start(&s_lcd_bl_pwm, LCD_BL_PWM_TIM_CHANNEL) != HAL_OK)
400	    {
401	        return -1;
402	    }
403	
404	    s_lcd_bl_pwm_running = true;
405	    s_bl_applied = brightness_pct;
406	    return 0;
407	}
