90	static int uart2loop_read_bytes(int fd, FAR char *buf, size_t want, int timeout_ms)
91	{
92	  size_t got = 0;
93	  struct pollfd pfd;
94	  ssize_t n;
95	
96	  while (got < want)
97	    {
98	      pfd.fd     = fd;
99	      pfd.events = POLLIN;
100	      if (poll(&pfd, 1, timeout_ms) <= 0)
101	        {
102	          break;
103	        }
104	
105	      n = read(fd, buf + got, want - got);
106	      if (n < 0)
107	        {
108	          if (errno == EAGAIN || errno == EINTR)
109	            {
110	              continue;
111	            }
112	
113	          return -errno;
114	        }
115	
116	      if (n == 0)
117	        {
118	          break;
119	        }
120	
121	      got += (size_t)n;
122	    }
123	
124	  return (int)got;
125	}
